const assert=require('assert');global.window={};require('../../assets/adaptive/lesson-cycle.js');const C=window.DEUTSCH_LESSON_CYCLE;
for(const count of [2,4,6,8,12]){const cards=Array.from({length:count},(_,i)=>({id:'phrase-'+i,de:'Phrase '+i}));for(let run=0;run<100;run++){const train=C.training(cards);assert.equal(train.length,count*5);C.types.forEach((type,round)=>{const part=train.slice(round*count,(round+1)*count);assert(part.every(q=>q.type===type&&q.round===round&&!q.assessment));assert.equal(new Set(part.map(q=>q.c.id)).size,count)});const exam=C.exam(cards);assert.equal(exam.length,count*3);assert(exam.every(q=>q.assessment&&q.type!=='speak'));for(let i=1;i<exam.length;i++)assert.notEqual(exam[i].c.id,exam[i-1].c.id);for(const c of cards){const qs=exam.filter(q=>q.c===c);assert.equal(qs.length,3);assert.equal(new Set(qs.map(q=>q.type)).size,3)}const totals=C.types.slice(0,4).map(type=>exam.filter(q=>q.type===type).length);assert(Math.max(...totals)-Math.min(...totals)<=1)}}
const q={c:{id:'x',de:'x'},type:'write'},r=ok=>({...q,ok,skipped:false});assert.equal(C.corrections([r(false)]).length,1);assert.equal(C.corrections([r(false),r(false)]).length,1);assert.equal(C.corrections([r(false),r(false),r(false)]).length,0);assert.equal(C.corrections([r(false),r(true)]).length,0);assert.equal(C.corrections([{...q,type:'speak',skipped:true,ok:false}],false).length,0);assert.equal(C.status([r(false),r(false),r(false)])[0].wrong,3);console.log('PASS full ordered training, balanced randomized 3-per-phrase tests, no adjacent phrase repeats and three-attempt correction bounds');
